```js
// Assumption: the landing bar is a named navigation region on the launchpad screen.
// The symptom is that its two entries stack vertically (column) instead of sitting in a row.
await page.goto('/ops/launchpad');
const bar = page.getByRole('navigation', { name: 'Landing' });
await expect(bar).toBeVisible();
await expect(bar).toHaveCSS('flex-direction', 'row');
await expect(bar.getByRole('link')).toHaveCount(2);
```

